-- Career Hub: rotina, treino, estafa, relações, progressão e decisões pré-partida.
-- A partida não é simulada aqui: o relógio para quando chega ao jogo.

CREATE SCHEMA IF NOT EXISTS private;

ALTER TABLE public.player_career_state
  ADD COLUMN IF NOT EXISTS fatigue INT NOT NULL DEFAULT 18 CHECK (fatigue BETWEEN 0 AND 100),
  ADD COLUMN IF NOT EXISTS form INT NOT NULL DEFAULT 50 CHECK (form BETWEEN 0 AND 100),
  ADD COLUMN IF NOT EXISTS cash_balance INT NOT NULL DEFAULT 0 CHECK (cash_balance >= 0),
  ADD COLUMN IF NOT EXISTS career_date DATE,
  ADD COLUMN IF NOT EXISTS day_period SMALLINT NOT NULL DEFAULT 0 CHECK (day_period BETWEEN 0 AND 2),
  ADD COLUMN IF NOT EXISTS next_match_date DATE,
  ADD COLUMN IF NOT EXISTS media_relation INT NOT NULL DEFAULT 50 CHECK (media_relation BETWEEN 0 AND 100),
  ADD COLUMN IF NOT EXISTS fan_relation INT NOT NULL DEFAULT 50 CHECK (fan_relation BETWEEN 0 AND 100),
  ADD COLUMN IF NOT EXISTS locker_room_relation INT NOT NULL DEFAULT 50 CHECK (locker_room_relation BETWEEN 0 AND 100),
  ADD COLUMN IF NOT EXISTS board_relation INT NOT NULL DEFAULT 50 CHECK (board_relation BETWEEN 0 AND 100),
  ADD COLUMN IF NOT EXISTS agent_relation INT NOT NULL DEFAULT 55 CHECK (agent_relation BETWEEN 0 AND 100),
  ADD COLUMN IF NOT EXISTS public_image INT NOT NULL DEFAULT 45 CHECK (public_image BETWEEN 0 AND 100),
  ADD COLUMN IF NOT EXISTS personal_life INT NOT NULL DEFAULT 60 CHECK (personal_life BETWEEN 0 AND 100),
  ADD COLUMN IF NOT EXISTS pressure INT NOT NULL DEFAULT 25 CHECK (pressure BETWEEN 0 AND 100),
  ADD COLUMN IF NOT EXISTS injury_status TEXT NOT NULL DEFAULT 'healthy' CHECK (injury_status IN ('healthy','minor')),
  ADD COLUMN IF NOT EXISTS injury_label TEXT,
  ADD COLUMN IF NOT EXISTS injury_days INT NOT NULL DEFAULT 0 CHECK (injury_days BETWEEN 0 AND 60),
  ADD COLUMN IF NOT EXISTS personality JSONB NOT NULL DEFAULT '{"professionalism":50,"ambition":50,"leadership":40,"discipline":50,"sociability":50,"ego":45}'::jsonb,
  ADD COLUMN IF NOT EXISTS weekly_objective JSONB NOT NULL DEFAULT '{}'::jsonb,
  ADD COLUMN IF NOT EXISTS last_salary_date DATE;

CREATE TABLE IF NOT EXISTS public.player_skill_development (
  player_id UUID NOT NULL REFERENCES public.jogadores(id) ON DELETE CASCADE,
  skill_key TEXT NOT NULL,
  label TEXT NOT NULL,
  category TEXT NOT NULL,
  parent_attribute TEXT NOT NULL,
  level INT NOT NULL CHECK (level BETWEEN 1 AND 99),
  progress NUMERIC(5,2) NOT NULL DEFAULT 0 CHECK (progress >= 0 AND progress < 100),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (player_id, skill_key)
);

CREATE TABLE IF NOT EXISTS public.player_career_actions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  player_id UUID NOT NULL REFERENCES public.jogadores(id) ON DELETE CASCADE,
  career_date DATE NOT NULL,
  day_period SMALLINT NOT NULL CHECK (day_period BETWEEN 0 AND 2),
  activity_key TEXT NOT NULL,
  category TEXT NOT NULL,
  title TEXT NOT NULL,
  intensity TEXT,
  duration_minutes INT,
  result_summary TEXT NOT NULL,
  hidden_effects JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_player_career_actions_player_date ON public.player_career_actions(player_id, career_date DESC, day_period DESC);

CREATE TABLE IF NOT EXISTS public.player_career_events (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  player_id UUID NOT NULL REFERENCES public.jogadores(id) ON DELETE CASCADE,
  event_key TEXT NOT NULL,
  source TEXT NOT NULL,
  title TEXT NOT NULL,
  body TEXT NOT NULL,
  choices JSONB NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','resolved','expired')),
  chosen_key TEXT,
  result_text TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  resolved_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_player_career_events_player_status ON public.player_career_events(player_id, status, created_at DESC);

ALTER TABLE public.player_skill_development ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.player_career_actions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.player_career_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.player_skill_development FROM anon, authenticated;
REVOKE ALL ON TABLE public.player_career_actions FROM anon, authenticated;
REVOKE ALL ON TABLE public.player_career_events FROM anon, authenticated;
GRANT SELECT ON TABLE public.player_skill_development TO authenticated;
GRANT SELECT ON TABLE public.player_career_actions TO authenticated;
GRANT SELECT ON TABLE public.player_career_events TO authenticated;
DROP POLICY IF EXISTS "Owner Skill Development Select" ON public.player_skill_development;
CREATE POLICY "Owner Skill Development Select" ON public.player_skill_development FOR SELECT TO authenticated USING (public.is_player_owner(player_id));
DROP POLICY IF EXISTS "Owner Career Actions Select" ON public.player_career_actions;
CREATE POLICY "Owner Career Actions Select" ON public.player_career_actions FOR SELECT TO authenticated USING (public.is_player_owner(player_id));
DROP POLICY IF EXISTS "Owner Career Events Select" ON public.player_career_events;
CREATE POLICY "Owner Career Events Select" ON public.player_career_events FOR SELECT TO authenticated USING (public.is_player_owner(player_id));

CREATE TABLE IF NOT EXISTS private.career_activity_catalog (
  activity_key TEXT PRIMARY KEY,
  category TEXT NOT NULL CHECK (category IN ('training','recovery','social','professional')),
  title TEXT NOT NULL, description TEXT NOT NULL, icon TEXT NOT NULL, load_label TEXT NOT NULL,
  supports_intensity BOOLEAN NOT NULL DEFAULT false, supports_duration BOOLEAN NOT NULL DEFAULT false,
  base_duration INT NOT NULL DEFAULT 60,
  energy_delta INT NOT NULL DEFAULT 0, fatigue_delta INT NOT NULL DEFAULT 0, morale_delta INT NOT NULL DEFAULT 0,
  trust_delta INT NOT NULL DEFAULT 0, form_delta INT NOT NULL DEFAULT 0, media_delta INT NOT NULL DEFAULT 0,
  fan_delta INT NOT NULL DEFAULT 0, locker_delta INT NOT NULL DEFAULT 0, board_delta INT NOT NULL DEFAULT 0,
  agent_delta INT NOT NULL DEFAULT 0, image_delta INT NOT NULL DEFAULT 0, personal_delta INT NOT NULL DEFAULT 0,
  pressure_delta INT NOT NULL DEFAULT 0, cash_delta INT NOT NULL DEFAULT 0,
  skill_effects JSONB NOT NULL DEFAULT '{}'::jsonb, base_injury_risk INT NOT NULL DEFAULT 0,
  result_summary TEXT NOT NULL, event_key TEXT
);

