('career_ambition','Empresário','Qual é sua prioridade?','Seu empresário pergunta que tipo de movimento deve priorizar quando surgirem oportunidades.','[{"key":"minutes","label":"“Quero jogar. Não adianta ir para um clube maior e ficar no banco.”","result":"Seu empresário entendeu que minutos terão prioridade nas próximas conversas.","effects":{"agent":3,"board":1,"fans":2,"ambition":-1,"professionalism":2}},{"key":"big_club","label":"“Se aparecer um clube grande, quero saber na hora.”","result":"Seu empresário vai trabalhar sua exposição de forma mais agressiva.","effects":{"agent":5,"board":-3,"fans":-3,"media":3,"image":2,"pressure":3,"ambition":5}},{"key":"money","label":"“Quero valorizar meu contrato. A parte financeira importa.”","result":"A conversa ficou mais comercial e objetiva.","effects":{"agent":4,"board":-2,"fans":-4,"image":1,"ambition":3,"ego":2}},{"key":"stay","label":"“Não quero pensar em sair agora.”","result":"A mensagem de estabilidade tende a repercutir bem internamente.","effects":{"agent":-1,"board":4,"fans":5,"coach":2,"locker":2,"pressure":-2}}]'),
